// ============================================================================
// NVMe_apb: APB4 register wrapper around NVMe_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/NVMe.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/NVMe.md
// ============================================================================
module NVMe_apb #(
  parameter int QD    = 8,
  // entries per queue (power of 2, 4 .. 16)
  parameter int NBLK  = 8,
  // namespace size, blocks (power of 2, at least 2)
  parameter int BLKDW = 4
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  output logic m_req_valid,
  input logic m_req_ready,
  output logic m_req_we,
  output logic [15:0] m_req_addr,
  output logic [31:0] m_req_wdata,
  input logic m_rsp_valid,
  input logic [31:0] m_rsp_data
);
  localparam logic [31:0] ID_VALUE = 32'h4E560200;

  // ---------------- core ----------------
  logic          c_cc_en;
  logic          c_csts_rdy;
  logic [15:0]   c_sq_base;
  logic [15:0]   c_cq_base;
  logic          c_sq_db_valid;
  logic [15:0]   c_sq_db;
  logic          c_cq_db_valid;
  logic [15:0]   c_cq_db;
  logic [2:0]    c_sq_head;
  logic [2:0]    c_cq_tail;
  logic          c_ev_cqe;
  logic          c_ev_err;
  logic          c_ev_db;
  NVMe_top #(.QD(QD), .NBLK(NBLK), .BLKDW(BLKDW)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .cc_en(c_cc_en),
    .csts_rdy(c_csts_rdy),
    .sq_base(c_sq_base),
    .cq_base(c_cq_base),
    .sq_db_valid(c_sq_db_valid),
    .sq_db(c_sq_db),
    .cq_db_valid(c_cq_db_valid),
    .cq_db(c_cq_db),
    .sq_head(c_sq_head),
    .cq_tail(c_cq_tail),
    .m_req_valid(m_req_valid),
    .m_req_ready(m_req_ready),
    .m_req_we(m_req_we),
    .m_req_addr(m_req_addr),
    .m_req_wdata(m_req_wdata),
    .m_rsp_valid(m_rsp_valid),
    .m_rsp_data(m_rsp_data),
    .ev_cqe(c_ev_cqe),
    .ev_err(c_ev_err),
    .ev_db(c_ev_db)
  );

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [9:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd10) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- registers ----------------
  logic [2:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [0:0] r_CC;   // 12'h014 CC
  logic [31:0] r_QBASE;   // 12'h018 QBASE
  logic [15:0] h_SQ_DB;   // 12'h01C SQ_DB holding register
  logic [15:0] h_CQ_DB;   // 12'h020 CQ_DB holding register
  logic vld_SQ_DB;
  logic vld_CQ_DB;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_CC <= 1'h0;
      r_QBASE <= 32'h0;
      h_SQ_DB <= '0;
      h_CQ_DB <= '0;
      vld_SQ_DB <= 1'b0;
      vld_CQ_DB <= 1'b0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[2:0] & wmask[2:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[2:0]) | (PWDATA[2:0] & wmask[2:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_CC <= (r_CC & ~wmask[0:0]) | (PWDATA[0:0] & wmask[0:0]);
      if (wr && hit[6]) r_QBASE <= (r_QBASE & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[7]) h_SQ_DB <= (h_SQ_DB & ~wmask[15:0]) | (PWDATA[15:0] & wmask[15:0]);
      vld_SQ_DB <= wr && hit[7];
      if (wr && hit[8]) h_CQ_DB <= (h_CQ_DB & ~wmask[15:0]) | (PWDATA[15:0] & wmask[15:0]);
      vld_CQ_DB <= wr && hit[8];
    end
  end

  // ---------------- core inputs ----------------
  assign c_cc_en = r_CC;
  assign c_sq_base = r_QBASE[15:0];
  assign c_cq_base = r_QBASE[31:16];
  assign c_sq_db[15:0] = h_SQ_DB[15:0];
  assign c_cq_db[15:0] = h_CQ_DB[15:0];
  assign c_sq_db_valid = vld_SQ_DB;
  assign c_cq_db_valid = vld_CQ_DB;

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_ev_cqe;
    irq_set[1] = c_ev_err;
    irq_set[2] = c_ev_db;
  end
  assign irq = |(irq_status & irq_enable);

  // ---------------- read mux ----------------
  logic [31:0] rdata;
  always_comb begin
    rdata = '0;
    case (PADDR[11:2])
      10'd0: rdata = ID_VALUE;
      10'd1: rdata = 32'(irq_status);
      10'd2: rdata = 32'(irq_enable);
      10'd4: rdata = scratch;
      10'd5: rdata = 32'(r_CC);
      10'd6: rdata = 32'(r_QBASE);
      10'd7: rdata = 32'(h_SQ_DB);
      10'd8: rdata = 32'(h_CQ_DB);
      10'd9: rdata = 32'({c_cq_tail, c_sq_head, c_csts_rdy});
      default: rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? rdata : '0;
endmodule
